const jid = $('Edit Fields6').first().json.message.number || '';
const digitos = jid.replace('@s.whatsapp.net', '').replace(/\D/g, '');
return {
  phone: digitos ? '+' + digitos : null,
  message: $input.first().json.messages.join('\n'),
  messageId: $('Edit Fields6').first().json.message.message_id,
};

const salida = String($input.first().json.output || '');
const escalar = salida.includes('[[ESCALAR]]');
const texto = salida.replace(/\[\[ESCALAR\]\]/g, '').trim();
return [{ json: { texto, escalar } }];

const id = $('Code2').first().json.messageId;
const telefono = $('Code2').first().json.phone;
const escalar = $('Preparar respuesta').first().json.escalar;
const tipos = ['mensaje_entrante', 'respuesta_enviada'].concat(escalar ? ['escalado_humano'] : []);
const timestamp = new Date().toISOString();
return tipos.map((tipo) => {
  const body = JSON.stringify({ mensajeId: tipo === 'mensaje_entrante' ? id : id + ':' + tipo, tipo, telefono });
  return { json: { timestamp, body } };
});

const bruto = String($input.first().json.output || '');
const agente = ((bruto.match(/\[\[AGENTE:([^\]]+)\]\]/i) || [])[1] || 'HESTIA')
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim().toUpperCase();
const motor = ((bruto.match(/\[\[MOTOR:([^\]]+)\]\]/i) || [])[1] || '').trim().toLowerCase() || null;
const escalar = bruto.includes('[[ESCALAR]]');
const respuesta = bruto.replace(/\[\[(AGENTE|MOTOR):[^\]]*\]\]/gi, '').replace(/\[\[ESCALAR\]\]/g, '').trim();
// Sin texto, el backend no lo acepta y responde en modo local.
return [{ json: { respuesta: respuesta || null, agente, motor, escalar } }];
